new SwingWorker<Report, Integer>() {
    protected Report doInBackground() { return buildReport(this::publish); }
    protected void process(List<Integer> chunks) {
        bar.setValue(chunks.get(chunks.size() - 1));
    }
    protected void done() {                     // runs on the EDT
        try { render(get()); } catch (Exception e) { showError(e); }
    }
}.execute();                                    // start now

